text:
{
  "title": "国会職員育児休業法の改正",
  "lead": {
    "es": "国会《こっかい》ではたらく人《ひと》が、子育《こそだ》てのために仕事《しごと》の時間《じかん》をへらせるしくみを広《ひろ》げる法律《ほうりつ》です。",
    "hs": "国会職員について、子育てのための「育児時間」の制度を広げる法律です。",
    "std": "国会職員について、一般職の国家公務員に準じて育児時間制度を拡充する法律。",
    "univ": "一般職の国家公務員に準じて、国会職員について育児時間制度を拡充する法律。"
  },
  "facts": [
    {
      "es": "国《くに》の役所《やくしょ》ではたらく人《ひと》（一般職《いっぱんしょく》の国家公務員《こっかこうむいん》）と同《おな》じように、国会《こっかい》ではたらく人《ひと》の「育児時間《いくじじかん》」のしくみを広《ひろ》げます。",
      "hs": "｜一般《いっぱん》職の国家公務員にならって、国会職員の育児時間（子育てのために｜勤務《きんむ》時間の一部を休めるしくみ）の制度を｜拡充《かくじゅう》します。",
      "std": "一般職の国家公務員に準じて、国会職員の育児時間制度を拡充する。",
      "univ": "一般職の国家公務員に準じて、国会職員について育児時間制度を拡充する。"
    },
    {
      "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞき、国家公務員《こっかこうむいん》の育児休業《いくじきゅうぎょう》の法律《ほうりつ》を変《か》える法律《ほうりつ》が使《つか》われ始《はじ》める日《ひ》から使《つか》われます。",
      "hs": "一部の規定を除き、「国家公務員の育児休業等に関する法律の一部を改正する法律」の｜施行《しこう》の日から｜施行《しこう》します。",
      "std": "一部の規定を除き、国家公務員の育児休業等に関する法律の一部を改正する法律の施行の日から施行する。",
      "univ": "この法律は、一部の規定を除き、国家公務員の育児休業等に関する法律の一部を改正する法律の施行の日から施行する。"
    }
  ]
}
